def maxSum(s, k):
    def dfs(node, depth, total):
        if not node:
            return 0
        left, right = node.split()
        left = int(left)
        right = int(right)
        total += left
        if depth % k == 0:
            total += right
        return dfs(right, depth + 1, total)

    return dfs(s[0].split(), 0, 0)
